// @ts-check
/**
 * T22 release build config plugin.
 *
 * android/ is generated by `expo prebuild` and gitignored, so release
 * signing can never live there by hand — this plugin injects it on every
 * prebuild. It makes two edits to android/app/build.gradle:
 *
 * 1. A `release` signingConfig that reads the keystore location and
 *    credentials from environment variables (never from the repo):
 *      SUMRAK_KEYSTORE_PATH      absolute path to the .keystore file
 *      SUMRAK_KEYSTORE_PASSWORD  keystore password
 *      SUMRAK_KEY_ALIAS          key alias
 *      SUMRAK_KEY_PASSWORD       key password
 *    When the env vars are absent at *Gradle* time, the release buildType
 *    falls back to the debug key (same behavior as stock Expo) so ordinary
 *    dev workflows never break; scripts/release-android.sh refuses to run
 *    without them, so a real release is always properly signed.
 *
 * 2. `ndk { abiFilters "arm64-v8a" }` in defaultConfig. The sherpa-onnx AAR
 *    ships JNI libs for all four ABIs (~392 MB debug APK, T11); the S24
 *    Ultra is arm64-only and the dev emulators on this Apple-Silicon Mac
 *    run arm64 system images, so every build strips the other three.
 *    (buildType-level ndk.abiFilters does NOT filter prebuilt AAR jniLibs —
 *    verified in T22; defaultConfig does. An Intel-emulator need would mean
 *    removing this.)
 */
const { withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

const SIGNING_BLOCK = `        release {
            // Injected by plugins/with-release-signing.js (T22). Reads the
            // keystore from env — no key material in the repo, ever.
            def sumrakStore = System.getenv("SUMRAK_KEYSTORE_PATH")
            if (sumrakStore) {
                storeFile file(sumrakStore)
                storePassword System.getenv("SUMRAK_KEYSTORE_PASSWORD")
                keyAlias System.getenv("SUMRAK_KEY_ALIAS")
                keyPassword System.getenv("SUMRAK_KEY_PASSWORD")
            }
        }
`;

/** @param {import('expo/config').ExpoConfig} config */
function withReleaseSigning(config) {
  // The RN gradle plugin merges `reactNativeArchitectures` into abiFilters,
  // so the property is the authoritative arch switch — the ndk block below
  // alone gets unioned away (verified in T22).
  config = withGradleProperties(config, (config) => {
    const props = config.modResults;
    const existing = props.find(
      (p) => p.type === 'property' && p.key === 'reactNativeArchitectures',
    );
    if (existing && existing.type === 'property') existing.value = 'arm64-v8a';
    else props.push({ type: 'property', key: 'reactNativeArchitectures', value: 'arm64-v8a' });
    return config;
  });
  return withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents;

    if (!gradle.includes('SUMRAK_KEYSTORE_PATH')) {
      // Add the release signingConfig right after the stock debug one.
      gradle = gradle.replace(
        /(signingConfigs\s*\{\s*\n\s*debug\s*\{[\s\S]*?\n\s*\}\n)/,
        `$1${SIGNING_BLOCK}`,
      );

      // Point the release buildType at it when the env is present.
      gradle = gradle.replace(
        /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
        '$1signingConfig System.getenv("SUMRAK_KEYSTORE_PATH") ? signingConfigs.release : signingConfigs.debug',
      );
    }

    if (!gradle.includes('abiFilters "arm64-v8a"')) {
      gradle = gradle.replace(
        /(\n)(\s*)(versionName "[^"]+"\n)/,
        '$1$2$3$2// arm64-only (T22): the sherpa-onnx AAR carries 4 ABIs; this app\n$2// targets exactly one arm64 device (+ arm64 emulators on this Mac).\n$2ndk { abiFilters "arm64-v8a" }\n',
      );
    }

    config.modResults.contents = gradle;
    return config;
  });
}

module.exports = withReleaseSigning;
